-- C10 / P10.5 — evidence-backed scheduling/publishing with exact-account authorization, idempotency and uncertain-outcome reconciliation.
create table if not exists public.command_center_social_publish_intents (
 owner_id uuid not null references auth.users(id) on delete cascade,
 intent_id text not null check(btrim(intent_id)<>''), brand_id text not null check(btrim(brand_id)<>''), account_id text not null check(btrim(account_id)<>''),
 draft_id text not null check(btrim(draft_id)<>''), draft_version integer not null check(draft_version>0), draft_content_hash text not null check(btrim(draft_content_hash)<>''),
 profile_key text not null check(btrim(profile_key)<>''), profile_version integer not null check(profile_version>0), idempotency_key text not null check(btrim(idempotency_key)<>''), scheduled_at timestamptz,
 authorization_ref text not null check(btrim(authorization_ref)<>''), authorization_account_id text not null check(btrim(authorization_account_id)<>''), authorization_observed_at timestamptz not null, authorization_expires_at timestamptz not null,
 required_scopes text[] not null default '{}'::text[], created_at timestamptz not null,
 primary key(owner_id,intent_id), unique(owner_id,idempotency_key), check(authorization_account_id=account_id), check(authorization_observed_at<authorization_expires_at)
);
create table if not exists public.command_center_social_publish_state_history (
 owner_id uuid not null, state_event_id text not null check(btrim(state_event_id)<>''), intent_id text not null, state text not null check(state in ('prepared','scheduled','submitting','uncertain','published','failed')),
 observed_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0), primary key(owner_id,state_event_id), unique(owner_id,intent_id,observed_at), foreign key(owner_id,intent_id) references public.command_center_social_publish_intents(owner_id,intent_id) on delete restrict
);
create table if not exists public.command_center_social_publish_attempt_history (
 owner_id uuid not null, attempt_event_id text not null check(btrim(attempt_event_id)<>''), attempt_id text not null check(btrim(attempt_id)<>''), intent_id text not null, account_id text not null check(btrim(account_id)<>''), idempotency_key text not null check(btrim(idempotency_key)<>''),
 state text not null check(state in ('submitted','acknowledged','failed','unknown')), provider_request_ref text not null check(btrim(provider_request_ref)<>''), response_ref text, external_publication_id text, observed_at timestamptz not null,
 primary key(owner_id,attempt_event_id), unique(owner_id,attempt_id,observed_at), foreign key(owner_id,intent_id) references public.command_center_social_publish_intents(owner_id,intent_id) on delete restrict,
 check(response_ref is null or btrim(response_ref)<>''), check(external_publication_id is null or btrim(external_publication_id)<>'')
);
create table if not exists public.command_center_social_publish_receipts (
 owner_id uuid not null, intent_id text not null, account_id text not null check(btrim(account_id)<>''), idempotency_key text not null check(btrim(idempotency_key)<>''), external_publication_id text not null check(btrim(external_publication_id)<>''), provider_ref text not null check(btrim(provider_ref)<>''), published_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0),
 primary key(owner_id,intent_id), unique(owner_id,account_id,external_publication_id), unique(owner_id,idempotency_key), foreign key(owner_id,intent_id) references public.command_center_social_publish_intents(owner_id,intent_id) on delete restrict
);
create or replace view public.command_center_social_publish_current with (security_invoker=true) as select distinct on(s.owner_id,s.intent_id) s.owner_id,s.intent_id,s.state,s.observed_at,s.evidence_refs,i.brand_id,i.account_id,i.draft_id,i.draft_version,i.draft_content_hash,i.profile_key,i.profile_version,i.idempotency_key,i.scheduled_at,i.authorization_ref,i.authorization_account_id,i.authorization_observed_at,i.authorization_expires_at,i.required_scopes from public.command_center_social_publish_state_history s join public.command_center_social_publish_intents i using(owner_id,intent_id) order by s.owner_id,s.intent_id,s.observed_at desc;
create or replace function public.command_center_reject_social_publish_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Social publish evidence is immutable'; end $$;
drop trigger if exists command_center_social_publish_intents_immutable on public.command_center_social_publish_intents; create trigger command_center_social_publish_intents_immutable before update or delete on public.command_center_social_publish_intents for each row execute function public.command_center_reject_social_publish_evidence_mutation();
drop trigger if exists command_center_social_publish_state_immutable on public.command_center_social_publish_state_history; create trigger command_center_social_publish_state_immutable before update or delete on public.command_center_social_publish_state_history for each row execute function public.command_center_reject_social_publish_evidence_mutation();
drop trigger if exists command_center_social_publish_attempt_immutable on public.command_center_social_publish_attempt_history; create trigger command_center_social_publish_attempt_immutable before update or delete on public.command_center_social_publish_attempt_history for each row execute function public.command_center_reject_social_publish_evidence_mutation();
drop trigger if exists command_center_social_publish_receipts_immutable on public.command_center_social_publish_receipts; create trigger command_center_social_publish_receipts_immutable before update or delete on public.command_center_social_publish_receipts for each row execute function public.command_center_reject_social_publish_evidence_mutation();
alter table public.command_center_social_publish_intents enable row level security; alter table public.command_center_social_publish_state_history enable row level security; alter table public.command_center_social_publish_attempt_history enable row level security; alter table public.command_center_social_publish_receipts enable row level security;
revoke all on table public.command_center_social_publish_intents,public.command_center_social_publish_state_history,public.command_center_social_publish_attempt_history,public.command_center_social_publish_receipts from public,anon,authenticated;
grant select,insert on table public.command_center_social_publish_intents,public.command_center_social_publish_state_history,public.command_center_social_publish_attempt_history,public.command_center_social_publish_receipts to authenticated; grant select on table public.command_center_social_publish_current to authenticated;
create policy p10_5_social_publish_intent_owner on public.command_center_social_publish_intents for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_5_social_publish_state_owner on public.command_center_social_publish_state_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_5_social_publish_attempt_owner on public.command_center_social_publish_attempt_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p10_5_social_publish_receipt_owner on public.command_center_social_publish_receipts for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
